[{"order":1,"type":"heading","text":"Template-Driven Forms in Angular"},{"order":2,"type":"paragraph","text":"Template-driven forms in Angular offer a straightforward way to build forms using HTML templates. They rely heavily on Angular directives and two-way data binding to manage form state and validation. This approach is often preferred for simpler forms or when you want to leverage your existing HTML skills."},{"order":3,"type":"subheading","text":"Setting Up the Project"},{"order":4,"type":"paragraph","text":"First, ensure you have the Angular FormsModule imported into your application module. This module provides the necessary directives for template-driven forms."},{"order":5,"type":"code","text":"import { BrowserModule } from '@angular/platform-browser';
import { NgModule } from '@angular/core';
import { FormsModule } from '@angular/forms'; // Import FormsModule

import { AppComponent } from './app.component';

@NgModule({
  declarations: [
    AppComponent
  ],
  imports: [
    BrowserModule,
    FormsModule // Add FormsModule to imports
  ],
  providers: [],
  bootstrap: [AppComponent]
})
export class AppModule { }"},{"order":6,"type":"subheading","text":"Creating a Basic Form"},{"order":7,"type":"paragraph","text":"Let's create a simple form with an input field for a user's name. We'll use the 'ngModel' directive for two-way data binding."},{"order":8,"type":"code","text":"<!-- app.component.html -->
<form>
  <label for="name">Name:</label>
  <input type="text" id="name" name="name" [(ngModel)]="name">
  <p>You entered: {{ name }}</p>
</form>"},{"order":9,"type":"code","text":"// app.component.ts
import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  name: string = '';
}"},{"order":10,"type":"paragraph","text":"In this example, '[(ngModel)]="name"' binds the input field's value to the 'name' property in the component. Any changes in the input field will update the 'name' property, and vice versa. The 'name' attribute on the input is crucial for Angular to track the form control."},{"order":11,"type":"subheading","text":"Form Submission"},{"order":12,"type":"paragraph","text":"To handle form submission, you can bind to the 'ngSubmit' event of the 'form' element."},{"order":13,"type":"code","text":"<!-- app.component.html -->
<form (ngSubmit)="onSubmit()">
  <label for="name">Name:</label>
  <input type="text" id="name" name="name" [(ngModel)]="name" required>
  <button type="submit" [disabled]="!form.valid">Submit</button>
</form>"},{"order":14,"type":"code","text":"// app.component.ts
import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  name: string = '';

  onSubmit() {
    console.log('Form submitted!', this.name);
    // You can send the data to a server here
  }
}"},{"order":15,"type":"paragraph","text":"The '(ngSubmit)="onSubmit()"' binds the form's submit event to the 'onSubmit()' method in the component.  The 'required' attribute adds a basic validation rule.  The submit button is disabled until the form is valid. To access the form's validity, we need to use a template reference variable."},{"order":16,"type":"subheading","text":"Template Reference Variables and Form Validation"},{"order":17,"type":"paragraph","text":"Template reference variables allow you to access DOM elements and Angular directives within your template. We can use them to access the 'NgForm' directive and check the form's validity."},{"order":18,"type":"code","text":"<!-- app.component.html -->
<form (ngSubmit)="onSubmit()" #form="ngForm">
  <label for="name">Name:</label>
  <input type="text" id="name" name="name" [(ngModel)]="name" required #nameInput="ngModel">
  <div *ngIf="nameInput.invalid && (nameInput.dirty || nameInput.touched)">
    <div *ngIf="nameInput.errors?.['required']">
      Name is required.
    </div>
  </div>
  <button type="submit" [disabled]="form.invalid">Submit</button>
</form>"},{"order":19,"type":"paragraph","text":"Here, '#form="ngForm"' creates a template reference variable named 'form' that refers to the 'NgForm' directive. We can then use 'form.valid' to check if the form is valid. Similarly, '#nameInput="ngModel"' creates a reference to the ngModel directive on the input, allowing us to check 'nameInput.invalid' and 'nameInput.errors'."},{"order":20,"type":"subheading","text":"Common Validation Attributes"},{"order":21,"type":"bullet_point","text":"'required': Specifies that the input field must be filled out."},{"order":22,"type":"bullet_point","text":"'minlength': Specifies the minimum length of the input value."},{"order":23,"type":"bullet_point","text":"'maxlength': Specifies the maximum length of the input value."},{"order":24,"type":"bullet_point","text":"'pattern': Specifies a regular expression that the input value must match."},{"order":25,"type":"subheading","text":"Conclusion"},{"order":26,"type":"paragraph","text":"Template-driven forms are a powerful tool for building forms in Angular. They offer a simple and intuitive way to manage form state and validation using HTML templates and Angular directives. While they might not be suitable for complex forms with dynamic requirements, they are an excellent choice for many common form scenarios."}]
